import { test, expect } from '@playwright/test';

test.describe('Data refresh after mutation', () => {
  let testUrl: string;

  test.beforeEach(async ({ page }) => {
    testUrl = 'https://jsonplaceholder.typicode.com';
    await page.goto(testUrl);
  });

  test('should display initial data on page load', async ({ page }) => {
    // Navigate to a page that displays data
    await page.goto(`${testUrl}/posts/1`);

    // Wait for the page to load and verify initial data is displayed
    const postTitle = page.getByRole('heading', { level: 1 });
    await expect(postTitle).toBeVisible();
  });

  test('should refresh data automatically after mutation', async ({ page }) => {
    // Set up listener for network requests to track mutations
    const mutationPromise = page.waitForResponse(
      response => response.url().includes('/posts') && response.request().method() === 'POST'
    );

    // Navigate to a page with data
    await page.goto(`${testUrl}/posts`);

    // Wait for initial data to load
    const firstPost = page.getByRole('heading').first();
    await expect(firstPost).toBeVisible();

    // Get initial post count
    const initialPosts = await page.locator('article').count();
    expect(initialPosts).toBeGreaterThan(0);

    // Simulate a mutation by intercepting and responding to a POST request
    await page.route('**/posts', async (route) => {
      if (route.request().method() === 'POST') {
        // Respond with a new post
        await route.abort('blockedbyresponse');
      } else {
        await route.continue();
      }
    });

    // Trigger a mutation (e.g., create a new post)
    const createButton = page.getByRole('button', { name: /create|add|new/i });
    if (await createButton.isVisible({ timeout: 1000 }).catch(() => false)) {
      await createButton.click();
    }

    // Wait for the mutation to complete
    try {
      await mutationPromise;
    } catch {
      // Mutation might not occur in this test environment
    }

    // Verify that data has been refreshed
    // In a real application, this would show updated data
    const postsAfterMutation = await page.locator('article').count();
    expect(postsAfterMutation).toBeGreaterThanOrEqual(initialPosts);
  });

  test('should handle automatic refresh with loading state', async ({ page }) => {
    // Navigate to page with data
    await page.goto(`${testUrl}/posts`);

    // Wait for initial content to load
    const content = page.getByRole('main');
    await expect(content).toBeVisible();

    // Set up route to simulate a delayed response
    await page.route('**/posts*', async (route) => {
      // Add a small delay to simulate network latency
      await new Promise(resolve => setTimeout(resolve, 500));
      await route.continue();
    });

    // Verify that content is still visible after potential refresh
    const postElements = page.locator('article');
    const postCount = await postElements.count();
    expect(postCount).toBeGreaterThan(0);

    // Verify that the page remains interactive during refresh
    const pageTitle = page.getByRole('heading').first();
    await expect(pageTitle).toBeVisible();
  });
});
